CREATE FUNCTION public.claim_collaboration_emails(p_limit integer DEFAULT 20) RETURNS SETOF public.notification_outbox LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 UPDATE public.notification_outbox o SET status='Cancelled',updated_at=now() WHERE status IN ('Pending','Failed') AND ( (category<>'invitation' AND (NOT EXISTS(SELECT 1 FROM public.workspace_members wm WHERE wm.workspace_id=o.workspace_id AND wm.user_id=o.user_id) OR EXISTS(SELECT 1 FROM public.notification_preferences np WHERE np.user_id=o.user_id AND np.email->>o.category='false'))) OR (event_key LIKE 'invite:%' AND NOT EXISTS(SELECT 1 FROM public.workspace_invitations i WHERE 'invite:'||i.id=o.event_key AND i.status='Pending' AND i.expires_at>now())));
 RETURN QUERY WITH picked AS (SELECT id FROM public.notification_outbox WHERE ((status IN ('Pending','Failed') AND next_attempt_at<=now()) OR (status='Sending' AND updated_at<now()-interval '15 minutes')) AND attempts<5 ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT least(greatest(p_limit,1),50)) UPDATE public.notification_outbox o SET status='Sending',attempts=o.attempts+1,updated_at=now() FROM picked WHERE o.id=picked.id RETURNING o.*;
 END $$;
REVOKE ALL ON FUNCTION public.claim_collaboration_emails(integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.claim_collaboration_emails(integer) TO service_role;
CREATE FUNCTION public.guard_member_departure() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.tasks SET assignee_id=NULL WHERE workspace_id=OLD.workspace_id AND assignee_id=OLD.user_id;UPDATE public.milestones SET owner_id=NULL WHERE workspace_id=OLD.workspace_id AND owner_id=OLD.user_id;DELETE FROM public.project_members WHERE workspace_id=OLD.workspace_id AND user_id=OLD.user_id;RETURN OLD;END $$;
REVOKE ALL ON FUNCTION public.guard_member_departure() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER member_departure BEFORE DELETE ON public.workspace_members FOR EACH ROW EXECUTE FUNCTION public.guard_member_departure();